export const BODY: string = "\n<p>چند تصاویر بدلنے کے لیے کسی نظام کی ضرورت نہیں۔ ہر ہفتے سینکڑوں تصاویر بدلنے کے لیے نظام چاہیے ہوتا ہے، اور ہموار ورک فلو اور گڑبڑ کے درمیان فرق چند عادات کا ہوتا ہے۔</p>\n<p>اچھا بیچ ورک فلو چار چیزوں کو پورا کرتا ہے: فولڈر کیسے منظم ہوں، فائلوں کے نام کیسے رکھے جائیں، کوالٹی کیسے چیک کی جائے، اور اصل کیسے آرکائیو کیے جائیں۔</p>\n<p>اس مضمون میں وہ ورک فلو دیا گیا ہے جسے آپ ہر بیچ کے لیے دوبارہ استعمال کر سکتے ہیں، چاہے آپ ویب سائٹ چلاتے ہوں، دکان چلاتے ہوں، یا تصویری آرکائیو رکھتے ہوں۔</p>\n<h2 id=\"why-workflow-matters\">پیمانے پر ورک فلو کیوں اہمیت رکھتا ہے</h2>\n<p>ایک بیچ معاف کرنے والا ہوتا ہے۔ آپ اندازے سے کام کر سکتے ہیں، غلطیاں ہاتھ سے ٹھیک کر سکتے ہیں، اور پھر بھی گھنٹے میں مکمل کر سکتے ہیں۔ ہفتے میں تین سو تصاویر کا بیچ بالکل معاف کرنے والا نہیں ہوتا۔</p>\n<p>نظام کے بغیر فائلیں اوور رائٹ ہو جاتی ہیں، فارمیٹ مل جاتے ہیں، اور کسی کو یاد نہیں رہتا کہ کون سی سیٹنگ استعمال ہوئی تھی۔ حجم بڑھنے پر کام تیز ہونے کے بجائے سست ہو جاتا ہے۔</p>\n<p>ورک فلو فیصلے ہٹا دیتا ہے۔ فولڈر ڈھانچہ طے ہوتا ہے، نام رکھنے کا اصول طے ہوتا ہے، اور کوالٹی جانچ طے ہوتی ہے، اس لیے ہر بیچ ایک ہی طرح چلتا ہے۔</p>\n<p>یہ مستقل مزاجی ہی بیچ کام کو پائیدار بناتی ہے۔ نیا ٹیم ممبر پہلے دن سے وہی عمل چلا سکتا ہے اور وہی نتیجہ پا سکتا ہے۔</p>\n<h2 id=\"folder-structure\">فولڈر ڈھانچہ جو پیمانے پر کام کرے</h2>\n<p>ہر کام کے لیے تین فولڈر استعمال کریں: source، output اور archive۔ Source میں اصل ہوتے ہیں، output میں بدلی ہوئی فائلیں، اور archive میں مکمل کام۔</p>\n<p>کبھی جگہ پر تبدیل نہ کریں۔ Source فولڈر کے اندر تبدیل کرنے سے اصل اوور رائٹ ہونے کا خطرہ ہوتا ہے، اور ایک غلطی ان فائلوں کو تباہ کر سکتی ہے جنہیں آپ دوبارہ نہیں بنا سکتے۔</p>\n<p>کام والے فولڈرز کے نام تاریخ اور مقصد سے رکھیں، جیسے 2026-11-product-photos۔ تاریخ والا فولڈر خود بخود ترتیب میں آتا ہے اور ایک نظر میں بتاتا ہے کہ کام کیا تھا۔</p>\n<p>Output فولڈر کے اندر source ڈھانچہ دہرائیں۔ اگر source میں جوتوں اور قمیضوں کے لیے ذیلی فولڈر ہوں تو output میں بھی وہی ذیلی فولڈر ہوں، تاکہ فائلیں اپنی جگہ پر رہیں۔</p>\n<h2 id=\"naming-rules\">بدلی ہوئی فائلوں کے نام رکھنے کے اصول</h2>\n<p>اصل فائل نام رکھیں اور صرف ایکسٹینشن بدلیں، اور تبدیلی کو نشان زد کرنے والا لاحقہ شامل کریں۔ red-shoes.png نامی فائل red-shoes-webp.webp بن جاتی ہے، مثال کے طور پر۔</p>\n<p>بلک کنورٹر کا اختیاری فائل نام لاحقہ یہ خود بخود کرتا ہے۔ -webp یا -converted جیسا لاحقہ آؤٹ پٹ کو اصل سے الگ رکھتا ہے بغیر دستی نام بدلے۔</p>\n<p>فائل ناموں میں جگہوں اور خاص حروف سے بچیں۔ جگہوں کے بجائے ہائفن، چھوٹے حروف، اور کوئی بریکٹ یا ایمپرسینڈ نہ استعمال کریں، کیونکہ ویب سرور اور اسکرپٹ ان سے پریشان ہوتے ہیں۔</p>\n<p>نام وضاحتی مگر مختصر رکھیں۔ blue-cotton-shirt-front.webp جیسا نام مفید ہے، IMG_4821-final-v2-fixed.webp جیسا نام نہیں۔</p>\n<h2 id=\"sorting-before-converting\">تبدیل کرنے سے پہلے بیچ کو ترتیب دینا</h2>\n<p>تبدیل کرنے سے پہلے فائلوں کو قسم کے حساب سے ترتیب دیں۔ تصاویر ایک بیچ میں، لوگو دوسرے میں، اور اسکرین شاٹس تیسرے میں، کیونکہ ہر گروپ کو مختلف سیٹنگ چاہیے ہوتی ہے۔</p>\n<p>تصاویر 80 سے 85 فیصد کوالٹی پر JPG یا WebP چاہتی ہیں۔ لوگو شفافیت محفوظ رکھتے ہوئے PNG یا WebP چاہتے ہیں۔ متن والے اسکرین شاٹس 85 فیصد پر WebP چاہتے ہیں۔</p>\n<p>پہلے ترتیب دینے کا مطلب ہے فی بیچ ایک سیٹنگ، جو بلک کنورٹر کے بہترین کام کرنے کا طریقہ ہے۔ ملا ہوا بیچ سمجھوتہ سیٹنگ مجبور کرتا ہے جو کسی کے لیے بھی مکمل موزوں نہیں ہوتی۔</p>\n<p>اپ لوڈ سے پہلے نقل اور مسترد شدہ فائلیں ہٹائیں۔ ہر اضافی فائل تبدیلی کا وقت لیتی ہے اور ZIP کو بھرا کرتی ہے، اس لیے فوری چھانٹی بعد میں محنت بچاتی ہے۔</p>\n<h2 id=\"quality-checks\">کوالٹی جانچ جو مسائل جلد پکڑتی ہے</h2>\n<p>باقی ڈاؤن لوڈ کرنے سے پہلے ہر بیچ کی پہلی پانچ فائلیں چیک کریں۔ تصویر، لوگو اور اسکرین شاٹ پر Compare ویوئر کھولیں، اور تصدیق کریں کہ سب درست لگتے ہیں۔</p>\n<p>بیچ خلاصے کے کل چیک کریں۔ اگر بدلا ہوا کل اصل کل سے بڑا ہو تو فارمیٹ انتخاب غلط تھا، اور آپ کو ڈاؤن لوڈ سے پہلے بدلنا چاہیے۔</p>\n<p>بیچ کے بیچ اور آخر سے ایک ایک فائل چیک کریں۔ سیٹنگ بیچ کے دوران نہیں بدلتی، مگر لمبی فہرست میں ایک عجیب فائل چھپ سکتی ہے۔</p>\n<p>ہر کام کے لیے استعمال شدہ سیٹنگ کا تحریری نوٹ رکھیں۔ WebP 85 percent, white matte جیسا ایک لائن ریکارڈ اگلے شخص کو اندازہ لگانے سے بچاتا ہے۔</p>\n<h2 id=\"handling-mixed-batches\">ملے ہوئے بیچ کو نرمی سے سنبھالنا</h2>\n<p>کبھی کبھی فولڈر کو صاف ترتیب نہیں دیا جا سکتا، اور ملا ہوا بیچ ناگزیر ہوتا ہے۔ اس صورت میں وہ سیٹنگ چنیں جو سب سے اہم فائلوں کے لیے موزوں ہو، اوسط کے لیے نہیں۔</p>\n<p>JPG جانے والے تصاویر اور لوگو کے ملے بیچ کے لیے پہلے لوگو چیک کریں۔ تصاویر JPG تبدیلی کو اچھی طرح برداشت کرتی ہیں، جبکہ غلط میٹ رنگ والا لوگو خراب لگتا ہے۔</p>\n<p>WebP جانے والے ملے بیچ کے لیے پہلے متن والے اسکرین شاٹس چیک کریں۔ WebP تصاویر اور لوگو کو اچھی طرح سنبھالتا ہے، مگر چھوٹا متن وہ جگہ ہے جہاں کم کوالٹی سیٹنگ سب سے پہلے ظاہر ہوتی ہے۔</p>\n<p>جب ملے بیچ میں ایک یا دو خاص فائلیں ہوں تو انہیں الگ بدلیں۔ مشکل فائلیں نکالیں، مرکزی بیچ چلائیں، پھر استثنا کو مخصوص سیٹنگ سے سنبھالیں۔</p>\n<h2 id=\"two-format-workflow\">ویب سائٹس کے لیے دو فارمیٹ والا ورک فلو</h2>\n<p>بہت سی ویب سائٹس کو ہر تصویر دو فارمیٹس میں چاہیے ہوتی ہے: تیز براؤزرز کے لیے جدید WebP اور پرانے سسٹمز کے لیے JPG فال بیک۔ بلک کنورٹر دو پاس سے اسے آسان بنا دیتا ہے۔</p>\n<p>بیچ ایک بار WebP میں چلائیں، ZIP ڈاؤن لوڈ کریں، پھر وہی اصل دوبارہ JPG میں چلائیں اور دوسرا ZIP ڈاؤن لوڈ کریں۔ اصل پاسوں کے درمیان قطار میں رہتے ہیں۔</p>\n<p>دونوں پاسوں کے لیے مختلف فائل نام لاحقے استعمال کریں، جیسے -webp اور -jpg۔ دونوں آؤٹ پٹ فولڈر الگ رہتے ہیں، اور کوئی فائل دوسری کو اوور رائٹ نہیں کرتی۔</p>\n<p>دونوں ورژن اپنی سائٹ پر اپ لوڈ کریں، WebP پہلے اور JPG فال بیک کے طور پر۔ جدید براؤزر WebP چنتے ہیں، پرانے JPG پر آتے ہیں، اور ہر ناظر تصویر دیکھتا ہے۔</p>\n<h2 id=\"archiving-originals\">تبدیلی کے بعد اصل آرکائیو کرنا</h2>\n<p>بیچ کے بعد اصل کو کبھی حذف نہ کریں۔ بدلی ہوئی فائل کبھی دوبارہ مکمل اصل نہیں بن سکتی، اور مستقبل کی ضروریات کا اندازہ ناممکن ہے۔</p>\n<p>کام مکمل ہونے کے بعد source فولڈر کو آرکائیو میں منتقل کریں۔ فی مہینہ آرکائیو فولڈر، جیسے archive-2026-11، پرانے کاموں کو بے ترتیبی کے بغیر ڈھونڈنے کے قابل رکھتا ہے۔</p>\n<p>اگر تصاویر اہمیت رکھتی ہیں تو آرکائیو کو الگ ڈرائیو یا کلاؤڈ بیک اپ پر رکھیں۔ بلاگ کے لیے مقامی فولڈر ٹھیک ہے، مگر کلائنٹ کام کو حقیقی بیک اپ چاہیے ہوتا ہے۔</p>\n<p>تبدیلی کی سیٹنگ کو آرکائیو فولڈر میں چھوٹی ٹیکسٹ فائل کے طور پر ریکارڈ کریں۔ مستقبل میں آپ موجودہ آپ کا شکریہ ادا کریں گے جب کلائنٹ وہی کام دوبارہ مانگے گا۔</p>\n<h2 id=\"team-workflows\">ٹیموں کے لیے بیچ ورک فلو</h2>\n<p>جب کئی لوگ تصاویر بدلتے ہیں تو ورک فلو لکھا ہوا ہونا چاہیے، یاد کیا ہوا نہیں۔ ایک صفحے کی چیک لسٹ زبانی روایت سے ہر بار بہتر ہوتی ہے۔</p>\n<p>چیک لسٹ میں فولڈر ڈھانچہ، نام رکھنے کا اصول، ڈیفالٹ کوالٹی سیٹنگ، اور کوالٹی جانچ ہونی چاہیے۔ اس پر عمل کرنے والا کوئی بھی وہی نتیجہ دیتا ہے۔</p>\n<p>بھیجنے سے پہلے ہر بیچ کا جائزہ لینے کے لیے ایک شخص مقرر کریں۔ دوسری آنکھیں غلط میٹ رنگ یا چھوٹی ہوئی فائل کو پکڑتی ہیں جسے کنورٹر کبھی جھنڈا نہیں لگاتا۔</p>\n<p>مشترکہ کام کے لیے مشترکہ نام استعمال کریں۔ اگر ایک شخص -webp اور دوسرا -web استعمال کرے تو آؤٹ پٹ فولڈر ایسی گڑبڑ بن جاتے ہیں جسے کوئی بعد میں سلجھا نہیں سکتا۔</p>\n<h2 id=\"automating-repetition\">دہرائے جانے والے حصوں کو خودکار کرنا</h2>\n<p>تبدیلی خود پہلے سے خودکار ہے، مگر ارد گرد کے مرحلے بھی ہو سکتے ہیں۔ سادہ اسکرپٹ جو فائلوں کو قسم کے حساب سے ترتیب دے یا نام مستقل رکھے، گھنٹے بچاتا ہے۔</p>\n<p>خودکاری کو ہلکا رکھیں۔ فولڈر ٹیمپلیٹ، نام رکھنے کا اصول، اور چیک لسٹ بغیر کسی کوڈ کے زیادہ تر دہراؤ کو پورا کر دیتے ہیں۔</p>\n<p>جہاں خودکار کریں، بورنگ حصوں کو خودکار کریں: ترتیب دینا، نام بدلنا، اور فولڈرز کے درمیان فائلیں منتقل کرنا۔ کوالٹی فیصلہ انسان پر چھوڑیں، کیونکہ کوئی اسکرپٹ آنکھ کی جگہ نہیں لے سکتا۔</p>\n<p>ورک فلو کا خود ہر چند ماہ بعد جائزہ لیں۔ پچاس تصاویر کے لیے معنی رکھنے والا اصول پانچ سو کے لیے موزوں نہیں ہو سکتا، اور چھوٹی ایڈجسٹمنٹ بڑی بچت کر سکتی ہے۔</p>\n<h2 id=\"common-workflow-mistakes\">عام ورک فلو غلطیاں</h2>\n<p>سب سے عام غلطی جگہ پر تبدیل کر کے اصل کو اوور رائٹ کرنا ہے۔ یہ ایک بار ہوتا ہے، اصل ختم ہو جاتے ہیں، اور سبق مشکل طریقے سے سیکھا جاتا ہے۔</p>\n<p>دوسری غلطی لمبے بیچ پر کوالٹی جانچ چھوڑنا ہے۔ تین سو فائلوں پر لگائی گئی غلط سیٹنگ تباہی ہے، جبکہ پانچ فائلوں پر وہی غلطی چھوٹی ہوتی ہے۔</p>\n<p>لوگ سیٹنگ ریکارڈ کرنا بھی بھول جاتے ہیں۔ تین مہینے بعد کسی کو یاد نہیں رہتا کہ پروڈکٹ فوٹو 80 یا 90 فیصد پر بدلی گئی تھی، اور نیا بیچ مختلف لگتا ہے۔</p>\n<p>آخر میں، آؤٹ پٹ فولڈرز کو آرکائیو کیے بغیر ڈھیر نہ ہونے دیں۔ آدھے مکمل آؤٹ پٹ فولڈرز سے بھرا ورک اسپیس سب کو سست کرتا ہے اور اہم فائلیں چھپاتا ہے۔</p>\n<h2 id=\"measuring-success\">ورک فلو کام کرتا ہے یا نہیں، یہ ناپنا</h2>\n<p>اچھا ورک فلو نمبروں میں نظر آتا ہے۔ ناپیں کہ بیچ کتنا وقت لیتا ہے، کتنی فائلیں ناکام ہوتی ہیں، اور کتنی بار بیچ دوبارہ کرنا پڑتا ہے۔</p>\n<p>اگر بیچ شاذ و نادر دوبارہ کرنے پڑیں اور ناکامیاں شاذ و نادر ہوں تو ورک فلو کام کر رہا ہے۔ اگر ہر دوسرے بیچ میں مسئلہ ہو تو عمل میں کچھ ٹھیک کرنا چاہیے۔</p>\n<p>ٹیم سے پوچھیں کہ رکاوٹ کہاں ہے۔ بیچ چلانے والا شخص جانتا ہے کہ کون سا مرحلہ وقت ضائع کرتا ہے، اور اس کا جواب کسی بھی نظریے سے زیادہ قیمتی ہے۔</p>\n<p>چھوٹی بہتریاں جمع ہوتی ہیں۔ فی بیچ پانچ منٹ بچانا، ہفتے میں تین بیچ، سال میں تیرہ گھنٹے بنتا ہے، جو سادہ چیک لسٹ پر حقیقی واپسی ہے۔</p>\n<h2 id=\"version-control\">بدلی ہوئی فائلوں کے لیے ورژن کنٹرول</h2>\n<p>بدلی ہوئی فائلوں کو بھی کوڈ جیسا ورژن کنٹرول چاہیے ہوتا ہے۔ مختلف سیٹنگ سے دو بار بدلی گئی فائل دو مختلف ورژن ہوتی ہے، اور انہیں ملانا الجھن پیدا کرتا ہے۔</p>\n<p>ورژن نشان زد کرنے کے لیے فائل نام لاحقہ استعمال کریں۔ -v2 یا -webp-85 جیسا لاحقہ بالکل بتاتا ہے کہ فائل کس تبدیلی سے آئی، بغیر اسے کھولے۔</p>\n<p>جب کام دوبارہ چلایا جائے تو فی ورژن تاریخ والا فولڈر رکھیں۔ 2026-11-17-webp-85 نامی فولڈر اس دن کے آؤٹ پٹ رکھتا ہے، اور پرانا فولڈر پچھلا ورژن رکھتا ہے۔</p>\n<p>پچھلے ورژن کو جگہ پر کبھی اوور رائٹ نہ کریں۔ اوور رائٹ پرانی فائلیں تباہ کر دیتا ہے، اور اگر نئے ورژن میں مسئلہ ہو تو واپس جانے کے لیے کچھ نہیں بچتا۔</p>\n<p>پرانے ورژن صرف تب حذف کریں جب نیا تصدیق ہو جائے۔ پہلے نیا بیچ چیک کریں، تصدیق کریں کہ وہ درست لگتا ہے، اور پھر پرانے کو آرکائیو یا حذف کریں۔</p>\n<h2 id=\"client-revisions\">کلائنٹ کی ترامیم سنبھالنا</h2>\n<p>کلائنٹ ترامیم مانگتے ہیں، اور اچھا ورک فلو انہیں پورا بیچ دوبارہ کیے بغیر سنبھالتا ہے۔ ماخذ فائلیں اور سیٹنگ نوٹ رکھیں، اور ترمیم فوری کام بن جاتی ہے۔</p>\n<p>جب کلائنٹ مختلف فارمیٹ مانگے تو اصل سے بدلیں، بدلی ہوئی فائلوں سے نہیں۔ دوسری نسل کی تبدیلی نقصان بڑھاتی ہے، جبکہ تازہ تبدیلی صاف ہوتی ہے۔</p>\n<p>جب کلائنٹ مختلف کوالٹی مانگے تو سلائیڈر بدلیں اور بیچ دوبارہ چلائیں۔ اصل پاسوں کے درمیان قطار میں رہتے ہیں، اس لیے ترمیم منٹوں میں ہو جاتی ہے۔</p>\n<p>نظر ثانی شدہ بیچ کو واضح لیبل دیں، جیسے -v2-client-feedback۔ واضح لیبل ترمیم مکمل ہونے کے بعد پرانے بیچ کو غلطی سے بھیجنے سے بچاتا ہے۔</p>\n<p>ہر کام کے لیے ترامیم کا مختصر لاگ رکھیں۔ فی ترمیم ایک لائن، تاریخ اور تبدیلی کے ساتھ، کام کی کہانی بتاتی ہے اور ایک ہی بحث دوبارہ ہونے سے بچاتی ہے۔</p>\n<h2 id=\"documenting-settings\">ٹیم کے لیے سیٹنگ دستاویز کرنا</h2>\n<p>جو ورک فلو ایک شخص کے ذہن میں رہتا ہے وہ اس شخص کے دور ہونے پر مر جاتا ہے۔ سیٹنگ لکھیں، اور کوئی بھی بیچ درست چلا سکتا ہے۔</p>\n<p>دستاویز کام والے فولڈر میں ایک ٹیکسٹ فائل ہو سکتی ہے۔ اس میں ماخذ فولڈر، ہدف فارمیٹ، کوالٹی، میٹ رنگ، اور فائل نام لاحقہ درج ہوتے ہیں۔</p>\n<p>دستاویز میں کوالٹی جانچ بھی شامل کریں۔ check the first five files with Compare جیسی لائن اگلے شخص کو بتاتی ہے کہ اچھا کیسا لگتا ہے۔</p>\n<p>جب کام بدلے تو دستاویز کا جائزہ لیں۔ نئی پروڈکٹ لائن یا ویب سائٹ کا نیا حصہ مختلف سیٹنگ چاہ سکتا ہے، اور نوٹ کو اس کی عکاسی کرنی چاہیے۔</p>\n<p>دستاویز مختصر رکھیں۔ ایک صفحے کی ہدایات پڑھی جاتی ہیں، جبکہ دستی نظر انداز ہو جاتا ہے، اور مقصد یہ ہے کہ بیچ کوئی بھی درست چلا سکے۔</p>\n<h2 id=\"scaling-up\">سینکڑوں سے ہزاروں تک پیمانہ بڑھانا</h2>\n<p>جو ورک فلو سینکڑوں تصاویر سنبھالتا ہے وہ ہزاروں پر دباؤ میں آ سکتا ہے۔ فولڈر ڈھانچہ، نام رکھنا، اور کوالٹی جانچ سب کو حجم کے ساتھ پیمانہ بڑھانا چاہیے۔</p>\n<p>ہزاروں فائلوں کو تاریخ والے کام فولڈرز میں تقسیم کریں، ہر ایک کے اپنے source، output اور archive کے ساتھ۔ پانچ ہزار فائلوں والا ایک فولڈر ناقابلِ انتظام ہوتا ہے، جبکہ چھوٹے فولڈر سنبھالنے کے قابل ہوتے ہیں۔</p>\n<p>اس پیمانے پر دہرائے جانے والے حصوں کو خودکار کریں۔ سادہ اسکرپٹ جو فائلوں کو قسم کے حساب سے ترتیب دے یا نام مستقل رکھے، سال بھر میں گھنٹے بچاتا ہے۔</p>\n<p>اس پیمانے پر ہر بیچ کے لیے جائزہ لینے والا مقرر کریں۔ دوسری آنکھیں غلط میٹ رنگ یا چھوٹی ہوئی فائل کو پکڑتی ہیں جسے کنورٹر کبھی جھنڈا نہیں لگاتا۔</p>\n<p>ہفتہ وار تھرو پٹ ناپیں۔ اگر بیچ سست ہو رہے ہیں تو رکاوٹ عام طور پر ترتیب دینا یا جائزہ لینا ہوتی ہے، تبدیلی خود نہیں، اور اس مرحلے کو ٹھیک کرنے سے رفتار واپس آتی ہے۔</p>\n<h2 id=\"handling-urgent-batches\">فوری بیچ سنبھالنا</h2>\n<p>فوری بیچ کو رفتار چاہیے ہوتی ہے، کمال نہیں۔ ڈیفالٹ سیٹنگ سے بدلیں، پہلی تین فائلیں چیک کریں، اور ZIP ڈاؤن لوڈ کریں، ہر فائل پر غور کرنے کے بجائے۔</p>\n<p>جب وقت کم ہو تو ترتیب دینے کا مرحلہ چھوڑیں۔ سمجھوتہ سیٹنگ والا ملا ہوا بیچ اس کامل بیچ سے بہتر ہوتا ہے جو آخری تاریخ کے بعد آئے۔</p>\n<p>فوری کام کے لیے 80 سے 85 فیصد ڈیفالٹ کوالٹی استعمال کریں۔ یہ زیادہ تر تصاویر کے لیے موزوں ہوتی ہے، اور نتیجہ آخری تاریخ کے لیے کافی اچھا ہوتا ہے، چاہے وہ کامل نہ ہو۔</p>\n<p>ہر فائل کا جائزہ لینے سے پہلے فوراً ZIP ڈاؤن لوڈ کریں۔ ڈاؤن لوڈ شدہ بیچ محفوظ ہوتا ہے، جبکہ براؤزر میں پڑا بیچ ٹیب بند ہونے پر کھو سکتا ہے۔</p>\n<p>آخری تاریخ گزرنے کے بعد فوری بیچ کا جائزہ لیں۔ پہنچائی گئی فائلوں کی فوری جانچ کسی بھی مسئلے کو پکڑتی ہے، اور اصل آپ کو اگلے دور کے لیے انہیں ٹھیک کرنے دیتے ہیں۔</p>\n<p>ورک فلو بیوروکریسی نہیں، یہ مستقبل کے کام کے لیے یادداشت کی مدد ہے۔ تین فولڈر سیٹ کریں، نام رکھنے کا اصول طے کریں، پہلی پانچ فائلیں چیک کریں، اور اصل کو آرکائیو کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"باقاعدہ بیچ تبدیلی کے لیے فولڈر کیسے منظم کروں؟","answer":"ہر کام کے لیے تین فولڈر استعمال کریں: اصل کے لیے source، بدلی ہوئی فائلوں کے لیے output، اور مکمل کاموں کے لیے archive۔ source فولڈر کے اندر کبھی تبدیل نہ کریں، کیونکہ اس سے اصل اوور رائٹ ہونے کا خطرہ ہوتا ہے۔ کام والے فولڈرز کے نام تاریخ اور مقصد سے رکھیں۔"},{"question":"بدلی ہوئی بیچوں کے لیے کون سا فائل نام لاحقہ استعمال کروں؟","answer":"ایسا لاحقہ استعمال کریں جو تبدیلی کو بیان کرے، جیسے -webp یا -jpg، تاریخ کے بجائے۔ لاحقہ بدلی ہوئی فائلوں کو اصل سے ٹکرانے سے بچاتا ہے جب وہ ایک ہی فولڈر میں ہوں۔ اسے مختصر اور مستقل رکھیں۔"},{"question":"کیا بلک تبدیلی سے پہلے تصاویر کو قسم کے حساب سے ترتیب دوں؟","answer":"ہاں، جب بھی ممکن ہو۔ تصاویر، لوگو اور اسکرین شاٹس میں سے ہر ایک کو مختلف سیٹنگ چاہیے ہوتی ہے، اور ترتیب دینے سے آپ ہر گروپ کو اس کا بہترین فارمیٹ اور کوالٹی دے سکتے ہیں۔ ملا ہوا بیچ سمجھوتہ سیٹنگ مجبور کرتا ہے جو کسی کے لیے بھی مکمل موزوں نہیں ہوتی۔"},{"question":"ویب سائٹ کو WebP اور JPG دونوں ورژن چاہیے ہوں تو کیا کروں؟","answer":"ایک ہی اپ لوڈ سے بیچ دو بار چلائیں: ایک بار WebP میں اور ایک بار JPG میں، فارمیٹ بدلنے سے پہلے ہر ZIP ڈاؤن لوڈ کریں۔ مختلف فائل نام لاحقے استعمال کریں، جیسے -webp اور -jpg، تاکہ آؤٹ پٹ الگ رہیں۔"},{"question":"بڑی بیچ تبدیلی میں سب سے بڑا خطرہ کیا ہے؟","answer":"اصل کو اوور رائٹ کرنا سب سے بڑا خطرہ ہے، اس کے بعد سینکڑوں فائلوں پر غلط سیٹنگ لگانا۔ دونوں کو ایک ہی عادات سے روکا جاتا ہے: الگ آؤٹ پٹ فولڈر میں بدلیں، فائل نام لاحقہ استعمال کریں، اور پہلی پانچ فائلیں چیک کریں۔"},{"question":"اپنے بیچ تبدیلی ورک فلو کا کتنی بار جائزہ لوں؟","answer":"ہر چند ماہ بعد، یا جب بھی حجم نمایاں طور پر بدلے۔ پچاس تصاویر ہفتہ وار کے لیے بنا ورک فلو پانچ سو پر دباؤ میں آ سکتا ہے۔ بیچ چلانے والوں سے پوچھیں کہ رکاوٹ کہاں ہے، اور اس کے مطابق ایڈجسٹ کریں۔"}];
